/// <returns>A new populated instance of <c>AAXSalesOrderConfirmedBusinessEventContract</c>.</returns>
public static AAXSalesOrderConfirmedBusinessEventContract newFromCustConfirmJour(CustConfirmJour _custConfirmJour)
{
    var contract = new AAXSalesOrderConfirmedBusinessEventContract();
    contract.initialize(_custConfirmJour);

    return contract;
}

/// <summary>
/// Initializes the contract fields from the source record.
/// </summary>
/// <param name="_custConfirmJour">The source CustConfirmJour record.</param>
private void initialize(CustConfirmJour _custConfirmJour)
{
